import{_ as e,o,c as r,a6 as t}from"./chunks/framework.De615z8S.js";const m=JSON.parse('{"title":"跨境画布：设计、节点与图层怎样衔接","description":"","frontmatter":{"id":"cross-border-canvas","title":"跨境画布：设计、节点与图层怎样衔接","chapter":"03","topic":"cross-border","tool_ids":["lovart","tapnow","photoshop","krita"],"status":"已公开","evidence_status":"原创教程与规划示范，尚未执行图像任务或后台上传","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["comfyui","invokeai","krita-diffusion","ecommerce-skills","background-replacement-workflow","ad-production-kit"],"platform_rule_ids":["amazon","shopify","shopee"],"order":23.8},"headers":[],"relativePath":"ecommerce/cross-border-canvas.md","filePath":"ecommerce/cross-border-canvas.md"}'),s={name:"ecommerce/cross-border-canvas.md"};function i(c,a,n,d,p,l){return o(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="跨境画布-设计、节点与图层怎样衔接" tabindex="-1">跨境画布：设计、节点与图层怎样衔接 <a class="header-anchor" href="#跨境画布-设计、节点与图层怎样衔接" aria-label="Permalink to &quot;跨境画布：设计、节点与图层怎样衔接&quot;">​</a></h1><p>一个跨境项目可以用三类画布分工：设计画布组织资料与方向，节点工作流复用图像处理，图层软件完成真实主体与准确文字。先按任务选择，不要求每个项目全套软件都使用。</p><h2 id="第1步-在设计画布安排项目" tabindex="-1">第1步：在设计画布安排项目 <a class="header-anchor" href="#第1步-在设计画布安排项目" aria-label="Permalink to &quot;第1步：在设计画布安排项目&quot;">​</a></h2><p>放入真实商品图、事实表、渠道矩阵和语言稿。建立素材、任务、候选、通过、返工与交付六区。每个任务卡显示SKU、市场、位置、准确文字、参考图角色和结果状态，使用<a href="/ai-visual-creation-handbook/prompts/P08">P08</a>组织。</p><p>Lovart／TapNow的实际按钮、节点连接和导出能力按当前入口确认。画布中画出了流程箭头，只能说明计划关联；实际跑过的步骤再标完成。</p><h2 id="第2步-用节点复用稳定步骤" tabindex="-1">第2步：用节点复用稳定步骤 <a class="header-anchor" href="#第2步-用节点复用稳定步骤" aria-label="Permalink to &quot;第2步：用节点复用稳定步骤&quot;">​</a></h2><p>先完成真实主体的分割与一张背景合成，再考虑复用。可研究的节点链是：读取实拍→前景／蒙版→生成背景→合成主体→检查→输出。若某个节点会重绘主体，就保留真实商品层作为后续合成依据。</p><p>记录具体工作流文件、ComfyUI版本、自定义节点、模型与依赖；断线、缺模型或运行报错分别记录。旧示例工作流可以用于理解结构，不能凭README速度或截图宣称当前环境已跑通。</p><h2 id="第3步-在图层软件完成交付" tabindex="-1">第3步：在图层软件完成交付 <a class="header-anchor" href="#第3步-在图层软件完成交付" aria-label="Permalink to &quot;第3步：在图层软件完成交付&quot;">​</a></h2><p>将真实主体、背景、接触阴影、准确文案分别存层。英文与日文各自排版，桌面横幅与手机稿重新布局。尺寸图的箭头和单位使用真实参数，不让模型猜。</p><p>保存后重新打开检查文字、蒙版和素材链接。PNG只证明平面导出；PSD或Krita文件是否存在、能否打开与编辑单独检查。Codex协作方式见<a href="/ai-visual-creation-handbook/workflows/codex-ps">PS方法</a>。</p><h2 id="第4步-回到渠道检查" tabindex="-1">第4步：回到渠道检查 <a class="header-anchor" href="#第4步-回到渠道检查" aria-label="Permalink to &quot;第4步：回到渠道检查&quot;">​</a></h2><p>把同一套事实母版对应到Amazon主图／A+、Shopify产品／横幅、Shopee封面／变体。检查的是具体位置与裁切，不能只看画布总览。把完成和未完成项写回交付清单。</p><p>本页提供制作路径与研究入口，尚未运行新节点、设计画布项目或创建PS／Krita源文件。</p>',14)])])}const _=e(s,[["render",i]]);export{m as __pageData,_ as default};
